-- Node.js + Express PostgreSQL schema for US24 Operations Portal.

CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "password" varchar(128) NOT NULL, "last_login" timestamp with time zone NULL, "is_superuser" boolean NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" boolean NOT NULL, "is_active" boolean NOT NULL, "date_joined" timestamp with time zone NOT NULL);

CREATE TABLE IF NOT EXISTS "tasks_userprofile" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "role" varchar(20) NOT NULL, "employee_id" varchar(50) NOT NULL, "phone" varchar(20) NOT NULL, "department" varchar(255) NOT NULL, "avatar_color" varchar(20) NOT NULL, "current_otp" varchar(6) NULL, "otp_created_at" timestamp with time zone NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE "tasks_userprofile" ALTER COLUMN "department" TYPE varchar(255);

CREATE TABLE IF NOT EXISTS "tasks_task" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "task_id" varchar(50) NOT NULL UNIQUE, "category" varchar(50) NOT NULL, "project_name" varchar(255) NOT NULL, "task_name" varchar(255) NOT NULL, "provider_name" varchar(255) NULL, "provider_effective_date" date NULL, "group_ptan" varchar(100) NOT NULL, "individual_ptan" varchar(100) NOT NULL, "early_start_date" date NULL, "sub_plan" varchar(255) NOT NULL, "address" varchar(500) NOT NULL DEFAULT '', "insurance_name" varchar(255) NOT NULL, "creation_date" date NOT NULL, "follow_up_type" varchar(20) NOT NULL, "follow_up_value" varchar(255) NOT NULL, "status" varchar(50) NOT NULL, "notes" text NOT NULL, "attachment" text NULL, "portal_link" varchar(500) NOT NULL, "portal_user_id" varchar(255) NOT NULL, "portal_password" varchar(255) NOT NULL, "work_date" date NULL, "follow_up_days" integer NULL CHECK ("follow_up_days" >= 0), "follow_up_due_date" date NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "assignee_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "created_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE "tasks_task" ADD COLUMN IF NOT EXISTS "address" varchar(500) NOT NULL DEFAULT '';
CREATE INDEX IF NOT EXISTS "tasks_task_assignee_id_2c3ca866" ON "tasks_task" ("assignee_id");
CREATE INDEX IF NOT EXISTS "tasks_task_created_by_id_1345568a" ON "tasks_task" ("created_by_id");
CREATE INDEX IF NOT EXISTS "tasks_task_category_status_created_idx" ON "tasks_task" ("category", "status", "created_at" DESC, "id" DESC);
CREATE INDEX IF NOT EXISTS "tasks_task_assignee_cat_created_idx" ON "tasks_task" ("assignee_id", "category", "created_at" DESC, "id" DESC);
CREATE INDEX IF NOT EXISTS "tasks_task_created_idx" ON "tasks_task" ("created_at" DESC, "id" DESC);

CREATE TABLE IF NOT EXISTS "tasks_tasklog" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "previous_status" varchar(50) NOT NULL, "new_status" varchar(50) NOT NULL, "remarks" text NOT NULL, "attachment" text NULL, "moc" varchar(20) NOT NULL, "tat" varchar(20) NOT NULL, "work_date" date NULL, "follow_up_days" integer NULL CHECK ("follow_up_days" >= 0), "portal_link" varchar(500) NOT NULL, "portal_user_id" varchar(255) NOT NULL, "portal_password" varchar(255) NOT NULL, "created_at" timestamp with time zone NOT NULL, "reassigned_to_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "task_id" bigint NOT NULL REFERENCES "tasks_task" ("id") DEFERRABLE INITIALLY DEFERRED, "updated_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS "tasks_tasklog_reassigned_to_id_8b8e162b" ON "tasks_tasklog" ("reassigned_to_id");
CREATE INDEX IF NOT EXISTS "tasks_tasklog_task_id_94d5b7eb" ON "tasks_tasklog" ("task_id");
CREATE INDEX IF NOT EXISTS "tasks_tasklog_updated_by_id_40bc68f1" ON "tasks_tasklog" ("updated_by_id");
CREATE INDEX IF NOT EXISTS "tasks_tasklog_task_created_idx" ON "tasks_tasklog" ("task_id", "created_at" DESC, "id" DESC);
CREATE INDEX IF NOT EXISTS "tasks_tasklog_created_idx" ON "tasks_tasklog" ("created_at" DESC, "id" DESC);

-- Login sessions for Node.js + Express authentication.
CREATE TABLE IF NOT EXISTS "node_session" ("session_key" varchar(64) NOT NULL PRIMARY KEY, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") ON DELETE CASCADE, "auth_hash" varchar(64) NOT NULL, "expire_date" timestamp with time zone NOT NULL);
CREATE INDEX IF NOT EXISTS "node_session_expire_date" ON "node_session" ("expire_date");

CREATE TABLE IF NOT EXISTS "tasks_paymentchecksheet" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "clinic" varchar(255) NOT NULL, "payer" varchar(255) NOT NULL, "eob_source" varchar(255) NOT NULL, "method" varchar(100) NOT NULL, "era_eob" varchar(100) NOT NULL, "check_no" varchar(100) NOT NULL, "check_date" date NULL, "check_amount" varchar(50) NOT NULL, "posted_amount" varchar(50) NOT NULL, "remaining_amount" varchar(50) NOT NULL, "recoupment" varchar(100) NOT NULL, "status" varchar(100) NOT NULL, "posted_date" date NULL, "posted_by" varchar(150) NOT NULL, "remarks" text NOT NULL, "clearance_date" date NULL, "error_note" varchar(255) NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "created_by_id" integer NULL REFERENCES "auth_user" ("id") ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS "tasks_paymentchecksheet_created_at" ON "tasks_paymentchecksheet" ("created_at");
CREATE INDEX IF NOT EXISTS "tasks_paymentchecksheet_created_by_id" ON "tasks_paymentchecksheet" ("created_by_id");
